// Services/Drone3DModel.cs
//
// VTOL QuadPlane 3D model (glTF binary) served to the 3D view at /drone.glb.
// glTF axes: +X nose, +Y up, +Z right wing. Real-world scale (2.16 m span, like
// the Loong 2160); the 3D page enlarges it on screen with minimumPixelSize.
// Generated by tools/make_drone_glb.py (Python + trimesh) - edit that, not this.

using System;

namespace InfraDroneDesktop.Services
{
    internal static class Drone3DModel
    {
        private static byte[]? _bytes;
        public static byte[] Glb => _bytes ??= Convert.FromBase64String(GlbBase64);

        private const string GlbBase64 = "";
    }
}
